import (
	"math"
	"strings"
	"unicode"
)

func Encode(pt string) string {
	normalized := normalize(pt)
	l := len(normalized)
	if l == 0 {
		return ""
	}

	c := int(math.Ceil(math.Sqrt(float64(l))))
	r := c
	if c*(c-1) >= l {
		r = c - 1
	}

	rows := make([]string, r)
	for i := 0; i < r; i++ {
		start := i * c
		end := start + c
		if end > l {
			end = l
		}
		row := normalized[start:end]
		if len(row) < c {
			row += strings.Repeat(" ", c-len(row))
		}
		rows[i] = row
	}

	chunks := make([]string, c)
	for col := 0; col < c; col++ {
		var sb strings.Builder
		for row := 0; row < r; row++ {
			sb.WriteByte(rows[row][col])
		}
		chunks[col] = sb.String()
	}

	return strings.Join(chunks, " ")
}

func normalize(s string) string {
	var sb strings.Builder
	for _, r := range s {
		if unicode.IsLetter(r) || unicode.IsDigit(r) {
			sb.WriteRune(unicode.ToLower(r))
		}
	}
	return sb.String()
}
"}

